// 单一真实session的有限查询接入：固定玩家、原DTO、会面暂停、旧页身份及恢复后拒绝；不重复规模矩阵。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/storage/common_codec.hpp"
#include <cassert>
#include <fstream>
#include <iostream>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;using D=BoundaryValue::Dict;using A=BoundaryValue::Array;
// 输入只能来自明确的原oracle；失败保留生产错误而不返回假空结果。
V read_file(const std::string& path){std::ifstream file(path);assert(file.good());std::string bytes((std::istreambuf_iterator<char>(file)),{});auto result=parse_boundary_json(bytes);assert(result.ok);return std::move(result.value);}
V object(std::initializer_list<std::pair<std::string,V>> fields){return V{D{fields}};}
V text(const std::string& value){return V{value};}
template<class T>T checked(Outcome<T> result){if(!result.ok){std::cerr<<result.error.original.code<<":"<<result.error.original.path<<"\n";std::abort();}return std::move(result.value);}
void require(Status result){if(!result.ok){std::cerr<<result.error.original.code<<":"<<result.error.original.path<<"\n";std::abort();}}
void exact(const V& expected,const V& actual){auto diff=compare_boundary(expected,actual);if(!diff.exact()){auto failure=diff.value_difference?diff.value_difference:diff.order_difference;std::cerr<<failure->path<<":"<<failure->reason<<"\n";if(auto fields=expected.as<D>()){std::cerr<<"expected_keys:";for(auto& row:*fields)std::cerr<<" "<<row.first;std::cerr<<"\n";}if(auto fields=actual.as<D>()){std::cerr<<"actual_keys:";for(auto& row:*fields)std::cerr<<" "<<row.first;std::cerr<<"\n";}std::abort();}}
bool okay(const V& value){auto p=value.find("ok");return p&&p->as<bool>()&&*p->as<bool>();}
std::string string(const V& value,const std::string& key){return boundary::get_string(value,key,"test");}
bool same(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
LiveOperation query(const WorldIdentity& source,const std::string& id,V args=object({})){return {LiveOperationKind::query,source,object({{"query_id",text(id)},{"args",std::move(args)}})};}
// 每条完成保发起和当前身份，读取本身不得推进revision/tick或绑定到另一个世界。
V read_query(ResidentReplaySession& session,const std::string& id,V args=object({})){auto identity=checked(session.identity());auto result=checked(session.execute_live(query(identity,id,std::move(args))));assert(same(result.source_identity,identity)&&same(result.current_identity,identity));return std::move(result.result);}
// 不把普通错误和外层调用失败混成成功；两者都必须留原世界与完整检查点。
void unchanged_failure(ResidentReplaySession& session,const LiveOperation& operation){auto before=checked(session.checkpoint());auto exported=checked(session.export_state());auto identity=checked(session.identity());auto failed=session.execute_live(operation);const auto* status=failed.ok?failed.value.result.find("ok"):nullptr;assert(!failed.ok||(status&&status->as<bool>()&&!*status->as<bool>()));assert(checked(session.checkpoint())==before&&same(checked(session.identity()),identity));exact(exported,checked(session.export_state()));}
// 真正command_context分配请求参数；该查询不预留序号，失败后同号仍可合法提交。
LiveOperation command(ResidentReplaySession& session,const std::string& kind,V params){auto context=read_query(session,"command_context");auto identity=checked(session.identity());return {LiveOperationKind::command,identity,object({{"kind",text(kind)},{"params",std::move(params)},{"actor_id",text(string(context,"actor_id"))},{"request_seq",*context.find("next_request_seq")},{"expected_revision",V{identity.revision}}})};}
// 在原walker-choice实际状态走拒绝、选择、restore与道别；不造业务数据或新增玩法。
void choice_flow(ResidentReplaySession& session,const V& original){auto checkpoint=checked(session.checkpoint());auto before=checked(session.identity());auto page=read_query(session,"interaction_view");auto old_page=query(before,"interaction_view",object({{"cursor",V{Integer{0}}}}));auto action=read_query(session,"action_context");assert(boundary::get_bool(action,"travel_paused","action"));assert(boundary::get_bool(read_query(session,"journey_input_need"),"needs_input","input"));
    LiveOperation advance{LiveOperationKind::preview,before,object({{"actor_id",text("actor.player")},{"kind",text("advance")},{"params",object({})}})};auto refused=checked(session.execute_live(advance));assert(!okay(refused.result)&&string(refused.result,"code")=="EncounterPending");assert(checked(session.checkpoint())==checkpoint);
    auto invalid=command(session,"dialogue_choose",object({{"option_id",text("not.a.visible.option")}}));auto declined=checked(session.execute_live(invalid));assert(!okay(declined.result)&&string(declined.result,"code")=="InvalidDialogueInput");assert(checked(session.checkpoint())==checkpoint);
    auto choice=string(original.find("options")->as<A>()->front(),"id");auto allowed=command(session,"dialogue_choose",object({{"option_id",text(choice)}}));auto receipt=checked(session.execute_live(allowed));assert(okay(receipt.result));auto now=checked(session.identity());assert(now.revision==before.revision+1&&now.tick==before.tick&&now.execution_epoch==before.execution_epoch);auto stale=session.execute_live(old_page);assert(!stale.ok&&stale.error.original.code=="StalePreview");auto answer=read_query(session,"interaction_view");assert(string(answer,"phase")=="say"&&string(answer,"speaker")=="actor.walker"&&!answer.find("options")&&!answer.find("page"));exact(*page.find("context"),*answer.find("context"));assert(boundary::get_bool(read_query(session,"action_context"),"travel_paused","action"));assert(boundary::get_bool(read_query(session,"journey_input_need"),"needs_input","input"));
    // 恢复回同一revision也必须换epoch，旧page/错误参数不能优先于StaleWorld门。
    require(session.restore(checkpoint));auto restored=checked(session.identity());assert(restored.world_id==before.world_id&&restored.execution_epoch!=before.execution_epoch&&restored.revision==before.revision&&restored.tick==before.tick);stale=session.execute_live(old_page);assert(!stale.ok&&stale.error.original.code=="StaleWorld");auto poisoned=query(before,"interaction_view",object({{"actor_id",text("actor.blackwater.commander")}}));stale=session.execute_live(poisoned);assert(!stale.ok&&stale.error.original.code=="StaleWorld");exact(page,read_query(session,"interaction_view"));
    auto meeting=read_query(session,"journey_encounter");auto leave=command(session,"encounter_leave",object({{"encounter_id",text(string(*meeting.find("encounter"),"encounter_id"))}}));assert(okay(checked(session.execute_live(leave)).result));assert(checked(session.identity()).tick==restored.tick);assert(!boundary::get_bool(read_query(session,"journey_input_need"),"needs_input","input"));assert(!boundary::get_bool(read_query(session,"action_context"),"travel_paused","action"));exact(object({{"phase",text("scene")}}),read_query(session,"interaction_view"));auto ended=read_query(session,"journey_encounter");assert(ended.find("encounter")->as<D>()->empty()&&!ended.find("dialogue_speaker"));assert(boundary::get_bool(*ended.find("travel"),"active","travel"));
}
}
// 四个原输入覆盖say、choice、未谈会面和含两支NPC军团的终态；每个session独立安装后始终只有一个core。
int main(int argc,char** argv){assert(argc==3);auto rows=read_file(argv[1]);std::string root=argv[2];auto resolve=[&](const std::string& path){return !path.empty()&&path.front()=='/'?path:root+"/"+path;};Integer cases=0;for(auto index:{1u,2u,4u,5u}){const auto& row=(*rows.as<A>())[index];auto source=read_file(resolve(string(row,"state")));auto session=create_resident_replay_session();require(session->initialize(read_file(resolve(string(row,"catalog"))),source));auto identity=checked(session->identity());auto checkpoint=checked(session->checkpoint());auto full=checked(session->export_state());auto& sidebar=*row.find("sidebar");V expected=object({{"travel",object({{"active",*sidebar.find("travel")->find("active")}})},{"encounter",*sidebar.find("encounter")}});auto speaker=sidebar.find("dialogue_speaker");if(!speaker->as<D>()->empty())expected.as<D>()->emplace_back("dialogue_speaker",*speaker);auto encounter=read_query(*session,"journey_encounter");exact(expected,encounter);auto dialogue=*row.find("dialogue");if(string(dialogue,"phase")=="choice")dialogue.as<D>()->emplace_back("page",object({{"cursor",V{Integer{0}}},{"total_rows",V{static_cast<Integer>(dialogue.find("options")->as<A>()->size())}}}));exact(dialogue,read_query(*session,"interaction_view"));exact(object({{"ok",V{true}},{"needs_input",*row.find("needs_input")}}),read_query(*session,"journey_input_need"));exact(object({{"ok",V{true}},{"logistics_quote",object({})}}),read_query(*session,"journey_logistics"));
        // 当前玩家不是NPC统帅；显式越权参数须拒绝，不能把任意军团变成“本军”。
        for(auto id:{"journey_encounter","journey_input_need","journey_logistics","interaction_view"})unchanged_failure(*session,query(identity,id,object({{"actor_id",text("actor.blackwater.commander")}})));unchanged_failure(*session,query(identity,"journey_logistics",object({{"army_id",text("army:262")}})));unchanged_failure(*session,query(identity,"interaction_view",object({{"cursor",V{Integer{-1}}}})));
        auto mismatched=identity;++mismatched.tick;auto stale=session->execute_live(query(mismatched,"interaction_view"));assert(!stale.ok&&stale.error.original.code=="StalePreview");assert(checked(session->checkpoint())==checkpoint&&same(checked(session->identity()),identity));exact(full,checked(session->export_state()));
        // 改写完成DTO只影响拥有值，不影响下一查询或状态。
        if(auto peer=encounter.find("encounter")->find("display_name"))*peer=text("display-only changed peer");else encounter.find("encounter")->as<D>()->emplace_back("display_only",text("changed"));exact(expected,read_query(*session,"journey_encounter"));auto held_dialogue=read_query(*session,"interaction_view");if(auto options=held_dialogue.find("options")){assert(!options->as<A>()->empty());*options->as<A>()->front().find("text")=text("display-only changed option");exact(dialogue,read_query(*session,"interaction_view"));}if(index==2)choice_flow(*session,*row.find("dialogue"));++cases;
    }assert(cases==4);std::cout<<"background_live_views: PASS (4 actual session query inputs; original C DTOs, trusted-player args, encounter pause/choice rejection, revision and restored-epoch page guards, read-only/deep-copy checks)\n";}
